import * as React from "react"
import { cva } from "class-variance-authority"
import { TrendingUpIcon, TrendingDownIcon, MinusIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

// ── Shared types ─────────────────────────────────────────────────────────────

export type CardStatFormat = "currency" | "percent" | "integer" | "float"
export type CardStatTrend = "up" | "down" | "neutral"
export type CardStatSize = "sm" | "md" | "lg"

// ── CVA variants ───────────────────────────────────────────────────────────────

export const cardStatLabelVariants = cva("", {
  variants: {
    size: {
      sm: "text-xs font-medium tracking-wide uppercase",
      md: "text-sm font-medium tracking-wide uppercase",
      lg: "text-base font-medium tracking-wide uppercase",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatValueVariants = cva("", {
  variants: {
    size: {
      sm: "text-xl font-semibold tracking-tight tabular-nums",
      md: "text-2xl font-semibold tracking-tight tabular-nums",
      lg: "text-3xl font-semibold tracking-tight tabular-nums",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatDescriptionVariants = cva("", {
  variants: {
    size: {
      sm: "text-xs",
      md: "text-xs",
      lg: "text-sm",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatHeaderIconVariants = cva("", {
  variants: {
    size: {
      sm: "size-3.5",
      md: "size-4",
      lg: "size-5",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatContentGapVariants = cva("", {
  variants: {
    size: {
      sm: "gap-2",
      md: "gap-3",
      lg: "gap-4",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatBadgePaddingVariants = cva("", {
  variants: {
    size: {
      sm: "px-1.5 py-0.5",
      md: "px-2 py-0.5",
      lg: "px-2.5 py-1",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatBadgeTextVariants = cva("", {
  variants: {
    size: {
      sm: "text-xs font-semibold",
      md: "text-xs font-semibold",
      lg: "text-sm font-semibold",
    },
  },
  defaultVariants: { size: "md" },
})

// ── Shared helpers ────────────────────────────────────────────────────────────

export function formatValue(
  value: string | number,
  format?: CardStatFormat,
  opts?: { decimals?: number; locale?: string; currency?: string }
): string {
  if (!format || typeof value === "string") return String(value)
  const num = Number(value)
  const locale = opts?.locale ?? "en-US"
  const currency = opts?.currency ?? "USD"
  const decimals = opts?.decimals
  switch (format) {
    case "currency":
      return new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        minimumFractionDigits: decimals ?? 2,
        maximumFractionDigits: decimals ?? 2,
      }).format(num)
    case "percent":
      return (
        new Intl.NumberFormat(locale, {
          minimumFractionDigits: decimals ?? 1,
          maximumFractionDigits: decimals ?? 1,
        }).format(num) + "%"
      )
    case "integer":
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      }).format(num)
    case "float":
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: decimals ?? 2,
        maximumFractionDigits: decimals ?? 2,
      }).format(num)
  }
}

export const TREND_ICONS: Record<CardStatTrend, React.ElementType> = {
  up: TrendingUpIcon,
  down: TrendingDownIcon,
  neutral: MinusIcon,
}

export const TREND_COLORS: Record<CardStatTrend, string> = {
  up: "text-success",
  down: "text-destructive",
  neutral: "text-muted-foreground",
}

export function resolveTrend(
  trend: CardStatTrend | boolean | undefined
): CardStatTrend | false {
  if (trend === true) return "up"
  if (!trend) return false
  return trend
}

export interface FmtProps {
  format?: CardStatFormat
  decimals?: number
  locale?: string
  currency?: string
  valueFormatter?: (value: number | string) => string
}

export function applyFmt(value: number | string, opts: FmtProps): string {
  return opts.valueFormatter
    ? opts.valueFormatter(value)
    : formatValue(value, opts.format, {
        decimals: opts.decimals,
        locale: opts.locale,
        currency: opts.currency,
      })
}

// ── TrendBadge ────────────────────────────────────────────────────────────────

export function TrendBadge({
  trend,
  value,
  size = "md",
}: {
  trend: CardStatTrend
  value: string
  size?: CardStatSize
}) {
  const Icon = TREND_ICONS[trend]
  return (
    <Badge
      className={cn(
        cardStatBadgePaddingVariants({ size }),
        cardStatBadgeTextVariants({ size }),
        trend === "up" && "bg-success/10 text-success",
        trend === "down" && "bg-destructive/10 text-destructive",
        trend === "neutral" && "bg-muted text-muted-foreground"
      )}
      data-slot="trend-badge"
    >
      <Icon aria-hidden />
      {value}
    </Badge>
  )
}

// ── CardStatEmptySlot ─────────────────────────────────────────────────────────

export function CardStatEmptySlot({
  icon: Icon,
  message,
  sub,
  inverted = false,
}: {
  icon: React.ElementType
  message: string
  sub?: string
  inverted?: boolean
}) {
  return (
    <div
      className="flex flex-col items-center justify-center gap-2 py-5 text-center"
      data-slot="card-stat-empty-slot"
    >
      <div
        className={cn(
          "flex size-9 items-center justify-center rounded-2xl",
          inverted ? "bg-white/15" : "bg-muted/60"
        )}
      >
        <Icon
          className={cn(
            "size-4",
            inverted ? "text-white/50" : "text-muted-foreground/50"
          )}
          aria-hidden
        />
      </div>
      <p
        className={cn(
          "text-xs font-medium",
          inverted ? "text-white/60" : "text-muted-foreground/70"
        )}
      >
        {message}
      </p>
      {sub && (
        <p
          className={cn(
            "text-xs leading-tight",
            inverted ? "text-white/40" : "text-muted-foreground/50"
          )}
        >
          {sub}
        </p>
      )}
    </div>
  )
}

import * as React from "react"
import { cva } from "class-variance-authority"
import { ActivityIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Card, CardContent } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

import {
  type CardStatTrend,
  type CardStatSize,
  type FmtProps,
  applyFmt,
  resolveTrend,
  TrendBadge,
  cardStatDescriptionVariants,
} from "./card-stats-shared"

// ── Types ──
export interface CardStatCompactProps extends FmtProps {
  label: string
  value: string | number
  trend?: CardStatTrend | boolean
  trendValue?: string
  icon?: React.ElementType
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
}

// ── Variants ──
export const cardStatCompactValueVariants = cva("", {
  variants: {
    size: {
      sm: "text-lg font-semibold tracking-tight tabular-nums",
      md: "text-xl font-semibold tracking-tight tabular-nums",
      lg: "text-2xl font-semibold tracking-tight tabular-nums",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatIconBoxVariants = cva("", {
  variants: {
    size: {
      sm: "size-9 rounded-xl",
      md: "size-10 rounded-2xl",
      lg: "size-12 rounded-2xl",
    },
  },
  defaultVariants: { size: "md" },
})

export const cardStatIconInnerVariants = cva("", {
  variants: {
    size: {
      sm: "size-4",
      md: "size-5",
      lg: "size-6",
    },
  },
  defaultVariants: { size: "md" },
})

export function CardStatCompact({
  label,
  value,
  trend,
  trendValue,
  icon: Icon,
  size = "md",
  className,
  loading,
  empty,
  ...fmt
}: CardStatCompactProps) {
  if (loading) {
    return (
      <Card size="sm" className={className} data-slot="card-stat-compact">
        <CardContent
          className="flex items-center gap-3 py-4"
          data-slot="card-stat-compact-skeleton"
        >
          <Skeleton
            className={cn(cardStatIconBoxVariants({ size }), "shrink-0")}
          />
          <div className="flex min-w-0 flex-1 flex-col gap-1.5">
            <Skeleton className="h-2.5 w-20 rounded-md" />
            <Skeleton className="h-6 w-28" />
          </div>
          <Skeleton className="h-5 w-14 rounded-full" />
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={className} data-slot="card-stat-compact">
        <CardContent
          className="flex items-center gap-3 py-4"
          data-slot="card-stat-compact-empty"
        >
          <div
            className={cn(
              "flex shrink-0 items-center justify-center bg-muted/50",
              cardStatIconBoxVariants({ size })
            )}
          >
            <ActivityIcon
              className={cn(
                cardStatIconInnerVariants({ size }),
                "text-muted-foreground/30"
              )}
              aria-hidden
            />
          </div>
          <div className="min-w-0 flex-1">
            <p
              className={cn(
                "truncate font-medium text-muted-foreground",
                cardStatDescriptionVariants({ size })
              )}
            >
              {label}
            </p>
            <p
              className={cn(
                cardStatCompactValueVariants({ size }),
                "text-muted-foreground/25"
              )}
            >
              —
            </p>
          </div>
          <span
            className={cn(
              cardStatDescriptionVariants({ size }),
              "text-muted-foreground/30"
            )}
          >
            No data
          </span>
        </CardContent>
      </Card>
    )
  }

  const display = applyFmt(value, fmt)
  const trendDir = resolveTrend(trend)

  return (
    <Card size="sm" className={className} data-slot="card-stat-compact">
      <CardContent className="flex items-center gap-3 py-4">
        {Icon && (
          <div
            className={cn(
              "flex shrink-0 items-center justify-center transition-colors",
              cardStatIconBoxVariants({ size }),
              trendDir === "up" && "bg-success/10",
              trendDir === "down" && "bg-destructive/10",
              !trendDir && "bg-muted"
            )}
          >
            <Icon
              className={cn(
                cardStatIconInnerVariants({ size }),
                trendDir === "up" && "text-success",
                trendDir === "down" && "text-destructive",
                !trendDir && "text-muted-foreground"
              )}
            />
          </div>
        )}
        <div className="min-w-0 flex-1">
          <p
            className={cn(
              "truncate font-medium text-muted-foreground",
              cardStatDescriptionVariants({ size })
            )}
          >
            {label}
          </p>
          <p className={cardStatCompactValueVariants({ size })}>{display}</p>
        </div>
        {trendDir && trendValue && (
          <TrendBadge trend={trendDir} value={trendValue} size={size} />
        )}
      </CardContent>
    </Card>
  )
}

import * as React from "react"
import { cva } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { Card, CardAction, CardContent, CardHeader } from "@/components/ui/card"
import { Progress } from "@/components/ui/progress"
import { Skeleton } from "@/components/ui/skeleton"

import {
  type CardStatSize,
  type FmtProps,
  applyFmt,
  cardStatLabelVariants,
  cardStatValueVariants,
  cardStatDescriptionVariants,
  cardStatHeaderIconVariants,
  cardStatContentGapVariants,
} from "./card-stats-shared"

// ── Variants ──
export const cardStatTrackHVariants = cva("", {
  variants: {
    size: {
      sm: "h-2",
      md: "h-3",
      lg: "h-4",
    },
  },
  defaultVariants: { size: "md" },
})

export interface CardStatProgressProps extends FmtProps {
  label: string
  value: number
  goal: number
  description?: string
  icon?: React.ElementType
  showPercent?: boolean
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
}

export function CardStatProgress({
  label,
  value,
  goal,
  description,
  icon: Icon,
  showPercent = true,
  size = "md",
  className,
  loading,
  empty,
  ...fmt
}: CardStatProgressProps) {
  if (loading) {
    return (
      <Card size="sm" className={className}>
        <CardHeader className="flex flex-row items-center justify-between">
          <Skeleton className="h-3 w-28 rounded-md" />
          <Skeleton
            className={cn(cardStatHeaderIconVariants({ size }), "rounded-md")}
          />
        </CardHeader>
        <CardContent
          className={cn("flex flex-col", cardStatContentGapVariants({ size }))}
        >
          <div className="flex items-baseline justify-between gap-2">
            <Skeleton className="h-7 w-24" />
            <Skeleton className="h-4 w-16 rounded-md" />
          </div>
          <Skeleton
            className={cn(cardStatTrackHVariants({ size }), "rounded-full")}
          />
          <div className="flex items-center justify-between">
            <Skeleton className="h-3 w-32 rounded-md" />
            <Skeleton className="h-3 w-8 rounded-md" />
          </div>
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={className}>
        <CardHeader className="flex flex-row items-center justify-between">
          <span
            className={cn(
              "truncate text-muted-foreground",
              cardStatLabelVariants({ size })
            )}
          >
            {label}
          </span>
          {Icon && (
            <CardAction className="text-muted-foreground">
              <Icon className={cardStatHeaderIconVariants({ size })} />
            </CardAction>
          )}
        </CardHeader>
        <CardContent
          className={cn("flex flex-col", cardStatContentGapVariants({ size }))}
        >
          <div className="flex items-baseline justify-between gap-2">
            <p
              className={cn(
                cardStatValueVariants({ size }),
                "text-muted-foreground/25"
              )}
            >
              —
            </p>
            <span
              className={cn(
                "shrink-0 text-muted-foreground/25",
                cardStatDescriptionVariants({ size })
              )}
            >
              / —
            </span>
          </div>
          <div
            className={cn(
              cardStatTrackHVariants({ size }),
              "w-full rounded-full border border-dashed border-muted-foreground/20"
            )}
          />
          <p
            className={cn(
              "text-center text-muted-foreground/50",
              cardStatDescriptionVariants({ size })
            )}
          >
            No goal set yet
          </p>
        </CardContent>
      </Card>
    )
  }

  const displayValue = applyFmt(value, fmt)
  const displayGoal = applyFmt(goal, fmt)
  const pct = Math.min(100, Math.round((value / goal) * 100))

  const pctColor =
    pct >= 100
      ? "text-success"
      : pct >= 75
        ? "text-highlight-sky"
        : pct >= 50
          ? "text-warning"
          : "text-muted-foreground"

  const barColor =
    pct >= 100
      ? "[&>[data-slot=progress-indicator]]:bg-success"
      : pct >= 75
        ? "[&>[data-slot=progress-indicator]]:bg-highlight-sky"
        : pct >= 50
          ? "[&>[data-slot=progress-indicator]]:bg-warning"
          : ""

  return (
    <Card size="sm" className={className}>
      <CardHeader className="flex flex-row items-center justify-between">
        <span
          className={cn(
            "truncate text-muted-foreground",
            cardStatLabelVariants({ size })
          )}
        >
          {label}
        </span>
        {Icon && (
          <CardAction className="text-muted-foreground">
            <Icon className={cardStatHeaderIconVariants({ size })} />
          </CardAction>
        )}
      </CardHeader>
      <CardContent
        className={cn("flex flex-col", cardStatContentGapVariants({ size }))}
      >
        <div className="flex items-baseline justify-between gap-2">
          <p className={cardStatValueVariants({ size })}>{displayValue}</p>
          <span
            className={cn(
              "shrink-0 text-muted-foreground",
              cardStatDescriptionVariants({ size })
            )}
          >
            / {displayGoal}
          </span>
        </div>
        <Progress
          value={pct}
          className={cn(cardStatTrackHVariants({ size }), barColor)}
        />
        <div className="flex items-center justify-between">
          {description && (
            <p
              className={cn(
                "text-muted-foreground",
                cardStatDescriptionVariants({ size })
              )}
            >
              {description}
            </p>
          )}
          {showPercent && (
            <p
              className={cn(
                "ml-auto font-semibold tabular-nums",
                cardStatDescriptionVariants({ size }),
                pctColor
              )}
            >
              {pct}%
            </p>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import * as React from "react"

import { cn } from "@/lib/utils"
import { Card, CardAction, CardContent, CardHeader } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

import {
  type CardStatTrend,
  type CardStatSize,
  type FmtProps,
  applyFmt,
  resolveTrend,
  TrendBadge,
  cardStatLabelVariants,
  cardStatValueVariants,
  cardStatDescriptionVariants,
  cardStatHeaderIconVariants,
} from "./card-stats-shared"

function toSvgPts(
  data: number[],
  w: number,
  h: number,
  pad = 4
): [number, number][] {
  if (data.length < 2) return []
  const min = Math.min(...data)
  const max = Math.max(...data)
  const range = max - min || 1
  return data.map((v, i) => [
    pad + (i / (data.length - 1)) * (w - pad * 2),
    pad + (h - pad * 2) - ((v - min) / range) * (h - pad * 2),
  ])
}

function catmullRom(pts: [number, number][], tension = 0.4): string {
  if (pts.length < 2) return ""
  if (pts.length === 2)
    return `M ${pts[0][0]} ${pts[0][1]} L ${pts[1][0]} ${pts[1][1]}`
  let d = `M ${pts[0][0]} ${pts[0][1]}`
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)]
    const p1 = pts[i]
    const p2 = pts[i + 1]
    const p3 = pts[Math.min(pts.length - 1, i + 2)]
    const cp1x = p1[0] + (p2[0] - p0[0]) * tension
    const cp1y = p1[1] + (p2[1] - p0[1]) * tension
    const cp2x = p2[0] - (p3[0] - p1[0]) * tension
    const cp2y = p2[1] - (p3[1] - p1[1]) * tension
    d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)} ${cp2x.toFixed(1)} ${cp2y.toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`
  }
  return d
}

function SparklineSvg({
  data,
  width = 120,
  height = 44,
  trend,
}: {
  data: number[]
  width?: number
  height?: number
  trend?: CardStatTrend | boolean
}) {
  const id = React.useId()
  const dir = resolveTrend(trend)
  const stroke =
    dir === "up"
      ? "var(--color-success)"
      : dir === "down"
        ? "var(--color-destructive)"
        : "currentColor"

  const pts = toSvgPts(data, width, height)
  const line = catmullRom(pts)
  const last = pts[pts.length - 1]
  const first = pts[0]
  const area =
    pts.length >= 2
      ? `${line} L ${last[0]} ${height} L ${first[0]} ${height} Z`
      : ""

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="shrink-0 overflow-visible"
      aria-hidden
    >
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" style={{ stopColor: stroke }} stopOpacity="0.22" />
          <stop offset="100%" style={{ stopColor: stroke }} stopOpacity="0" />
        </linearGradient>
      </defs>
      {area && <path d={area} fill={`url(#sg-${id})`} />}
      {line && (
        <path
          d={line}
          fill="none"
          style={{ stroke }}
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
      {last && (
        <circle cx={last[0]} cy={last[1]} r="2.5" style={{ fill: stroke }} />
      )}
    </svg>
  )
}

function FlatSparklineSvg({
  width = 120,
  height = 44,
}: {
  width?: number
  height?: number
}) {
  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="shrink-0 overflow-visible"
      aria-hidden
    >
      <line
        x1="4"
        y1={height / 2}
        x2={width - 4}
        y2={height / 2}
        stroke="currentColor"
        className="text-muted-foreground/25"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeDasharray="6 4"
      />
    </svg>
  )
}

export interface CardStatSparklineProps extends FmtProps {
  label: string
  value: string | number
  data?: number[]
  trend?: CardStatTrend | boolean
  trendValue?: string
  description?: string
  icon?: React.ElementType
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
}

export function CardStatSparkline({
  label,
  value,
  data = [],
  trend,
  trendValue,
  description,
  icon: Icon,
  size = "md",
  className,
  loading,
  empty,
  ...fmt
}: CardStatSparklineProps) {
  const sparklineW = size === "sm" ? 90 : size === "lg" ? 150 : 120
  const sparklineH = size === "sm" ? 32 : size === "lg" ? 56 : 44

  if (loading) {
    return (
      <Card size="sm" className={className} data-slot="card-stat-sparkline">
        <CardHeader className="flex flex-row items-center justify-between">
          <Skeleton className="h-3 w-28 rounded-md" />
          <Skeleton
            className={cn(cardStatHeaderIconVariants({ size }), "rounded-md")}
          />
        </CardHeader>
        <CardContent
          className="flex items-end justify-between gap-4"
          data-slot="card-stat-sparkline-skeleton"
        >
          <div className="flex flex-col gap-1.5">
            <Skeleton className="h-7 w-28" />
            <Skeleton className="h-5 w-24 rounded-full" />
          </div>
          <Skeleton
            className="rounded-xl"
            style={{ height: sparklineH, width: sparklineW }}
          />
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={className} data-slot="card-stat-sparkline">
        <CardHeader className="flex flex-row items-center justify-between">
          <span
            className={cn(
              "truncate text-muted-foreground",
              cardStatLabelVariants({ size })
            )}
          >
            {label}
          </span>
          {Icon && (
            <CardAction className="text-muted-foreground">
              <Icon className={cardStatHeaderIconVariants({ size })} />
            </CardAction>
          )}
        </CardHeader>
        <CardContent
          className="flex items-end justify-between gap-4"
